public class PizzaTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(Pizza.Builder builder) {
        try {
            Pizza pizza = builder.build();
            if (pizza == null) return "build() returned null";
            return pizza.describe();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("size only", "small pizza",
                describe(new Pizza.Builder("small")));
        check("cheese only", "medium pizza with cheese",
                describe(new Pizza.Builder("medium").cheese()));
        check("one topping uses singular", "small pizza with 1 topping",
                describe(new Pizza.Builder("small").addTopping("basil")));
        check("cheese and two toppings", "large pizza with cheese and 2 toppings",
                describe(new Pizza.Builder("large").cheese()
                        .addTopping("ham").addTopping("olive")));
        check("three toppings, no cheese", "large pizza with 3 toppings",
                describe(new Pizza.Builder("large").addTopping("ham")
                        .addTopping("olive").addTopping("onion")));
        check("chained calls keep the required size", "extra-large pizza with cheese",
                describe(new Pizza.Builder("extra-large").cheese()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

