public class Pizza {

    private final String size;
    private final boolean cheese;
    private final java.util.List<String> toppings;

    private Pizza(String size, boolean cheese, java.util.List<String> toppings) {
        this.size = size;
        this.cheese = cheese;
        this.toppings = toppings;
    }

    public String describe() {
        StringBuilder sb = new StringBuilder(size).append(" pizza");
        int n = toppings.size();
        if (cheese && n > 0) {
            sb.append(" with cheese and ").append(n).append(n == 1 ? " topping" : " toppings");
        } else if (cheese) {
            sb.append(" with cheese");
        } else if (n > 0) {
            sb.append(" with ").append(n).append(n == 1 ? " topping" : " toppings");
        }
        return sb.toString();
    }

    public static class Builder {
        private final String size;
        private boolean cheese = false;
        private final java.util.List<String> toppings = new java.util.ArrayList<>();

        public Builder(String size) {
            this.size = size;
        }

        public Builder cheese() {
            this.cheese = true;
            return this;
        }

        public Builder addTopping(String topping) {
            toppings.add(topping);
            return this;
        }

        public Pizza build() {
            return new Pizza(size, cheese, toppings);
        }
    }
}
